pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 value, address target) public {
        // Restrict to admissible domain: positive value and no precompile interference
        vm.assume(value > 0 && value <= address(c).balance);
        vm.assume(target != address(0) && target != address(c) && target != address(this));

        // Ensure the contract has enough Ether to send
        vm.deal(address(c), value + 1 ether);

        address owner = c.owner();
        vm.prank(owner);
        try c.sendMoney(target, value, "") {} catch {}

        // After the call, the owner should still be able to withdraw all funds.
        // The buggy version's onlyOwner always reverts, so withdrawAll() will fail.
        bool ok;
        vm.prank(owner);
        try c.withdrawAll() { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}

