pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address target, uint256 value, bytes memory data) public {
        // Keep the amount within the balance we provide; ensure sender is owner
        vm.assume(value <= address(this).balance);
        // Ensure target is not the contract itself to avoid simple self-call edge cases
        vm.assume(target != address(c));

        // Fund the owner (this contract is the owner) and call sendMoney
        vm.deal(address(this), value);
        vm.prank(address(this));
        (bool sent, ) = address(c).call{value: value}(abi.encodeWithSignature("sendMoney(address,uint256,bytes)", target, value, data));
        require(sent, "sendMoney call failed");

        // Now check that withdrawAll() does not revert
        bool withrawSucceeded;
        try c.withdrawAll() {
            withrawSucceeded = true;
        } catch {
            withrawSucceeded = false;
        }

        // On correct C withdrawAll always succeeds for the legitimate owner;
        // buggy modifier revert makes it fail.
        assertTrue(withrawSucceeded);
    }
}

