pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value, bytes calldata data) public {
        // 1. admissible domain: target may be the contract itself, value any, data any
        vm.assume(target != address(0));
        // 2. adversarial counterparty: the difference arises when sendMoney targets c itself,
        //    causing the fallback to fire and increment depositsCount. We must make the helper address
        //    set to c so that a low-level call from sendMoney triggers c's fallback.
        target = address(c);
        // Record depositsCount before the call
        uint256 depositsBefore = c.depositsCount();
        // Use a non-owner actor to trigger the bug
        address nonOwner = address(0x1234);
        vm.deal(nonOwner, value);
        vm.prank(nonOwner);
        // For the reference (no bug), this must revert; for the mutant, it can succeed if onlyOwner is missing.
        // We wrap in try/catch to observe revert booleans.
        bool ok = true;
        try c.sendMoney(target, value, data) {
            ok = true;
        } catch {
            ok = false;
        }
        // 3. general rule: if the call succeeded (non-owner call did not revert),
        //    depositsCount must equal depositsBefore + 1 because the onlyOwner modifier
        //    would prevent non-owner from calling sendMoney in the reference, so success
        //    implies the bug is present and depositsCount was incremented.
        //    Equivalent: either the call reverted (reference) OR depositsCount == depositsBefore + 1 (bug).
        //    The reference satisfies ok == false for all inputs; the bug makes ok true for some,
        //    and then depositsCount must be depositsBefore + 1.
        assertTrue(!ok || c.depositsCount() == depositsBefore + 1);
    }
}

