pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 sendValue) public {
        vm.assume(amount > 0 && amount <= address(this).balance);
        vm.assume(sendValue > 0 && sendValue <= amount);
        // Deploy a re-entrant helper that calls withdrawAll when receiving ETH
        ReentrantAttacker attacker = new ReentrantAttacker(c);
        vm.deal(address(this), amount);
        // Fund the contract so it has something to steal
        vm.prank(address(this));
        (bool fundResult, ) = address(c).call{value: amount}("");
        require(fundResult, "fund failed");
        uint256 initialOwnerBalance = address(c).balance;
        // Non-owner (address(0x1234)) calls sendMoney targeting the re-entrant attacker
        vm.prank(address(0x1234));
        try c.sendMoney(address(attacker), sendValue, "") {
            // if call doesn't revert, check rule
            uint256 finalOwnerBalance = address(c).balance;
            // In the reference, onlyOwner prevents withdrawAll re-entrancy, so balance stays == initialOwnerBalance.
            // In the mutant, withdrawAll succeeds re-entrantly, reducing balance below initialOwnerBalance.
            assertTrue(finalOwnerBalance == initialOwnerBalance);
        } catch {
            // Reference reverts (non-owner sends), so no state change can occur.
            // Assertion passes trivially.
        }
    }
}

contract ReentrantAttacker {
    C public target;
    constructor(C _target) { target = _target; }
    fallback() external payable {
        target.withdrawAll();
    }
}

