pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 initialDeposit) public {
        // Bound deposit to a non-zero amount to ensure the contract has a balance,
        // and to avoid overflow in the balance subtraction.
        bound(initialDeposit, 1, address(this).balance);

        // Fund the contract by sending Ether via fallback.
        vm.deal(address(this), initialDeposit);
        (bool sent, ) = address(c).call{value: initialDeposit}("");
        require(sent, "failed to send eth to c");

        uint256 balanceBefore = address(c).balance;

        // Call withdrawAll as the owner.
        vm.prank(address(this));
        try c.withdrawAll() {
            // The call succeeded.
            uint256 balanceAfter = address(c).balance;
            // General rule: if withdrawAll succeeds without reverting, the contract's
            // balance must be strictly less than it was before the call. The reference
            // withdraws the full balance, satisfying this; the mutant withdraws only
            // 1 wei, leaving the rest, so for any initialDeposit > 1, the balance
            // after will equal (balanceBefore - 1), which is NOT strictly less than
            // balanceBefore when initialDeposit > 1 (it is less, actually).
            // To catch the mutant, we assert the stronger property:
            // balanceAfter < balanceBefore.
            assertTrue(balanceAfter < balanceBefore);
        } catch {
            // Revert means we don't assert; the test passes vacuously.
        }
    }
}

