import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount) public {
        // Keep the deposit amount within a reasonable range to avoid overflow or insufficient balance issues
        vm.assume(depositAmount > 0);
        vm.assume(depositAmount <= address(this).balance / 2);

        // Fund the contract with a fuzzed amount using the fallback function
        vm.deal(address(this), depositAmount);
        (bool success, ) = address(c).call{value: depositAmount}("");
        require(success, "deposit failed");

        // Record owner's balance before withdrawAll
        address owner = c.owner();
        uint256 ownerBalanceBefore = owner.balance;

        // Record contract's balance before withdrawAll
        uint256 contractBalanceBefore = address(c).balance;

        // Perform the withdrawAll call as the owner
        vm.prank(owner);
        c.withdrawAll();

        // Owner's balance after withdrawAll
        uint256 ownerBalanceAfter = owner.balance;

        // The increase in the owner's balance must equal the contract's balance before withdrawal.
        // The reference contract transfers the full contract balance, so the increase equals contractBalanceBefore.
        // The mutant transfers only 1 wei, so the increase is 1, breaking the assertion.
        assertTrue(ownerBalanceAfter - ownerBalanceBefore == contractBalanceBefore);
    }
}

