pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address sender, uint256 value, bytes memory data) public {
        vm.assume(sender != address(0));
        vm.assume(sender != address(this));

        Reverter reverter = new Reverter();
        vm.deal(sender, value);

        vm.prank(sender);
        bool ok;
        try c.sendMoney(address(reverter), value, data) { ok = true; } catch { ok = false; }

        // Reference: sender != owner -> onlyOwner modifier fails -> sendMoney always reverts (ok == false).
        // Buggy: sender != owner -> modifier passes -> low-level call goes to Reverter, which reverts,
        // making sendMoney revert as well.  But the Adversarial counterparty "NeverRevert" reverses this -
        // see below.  Because the initial attempt also goes to a Reverter, both reference and buggy revert -
        // not a differentiator.  Thus we need an adversarial callee that REVERTS in the reference but
        // DOES NOT REVERT in the buggy, or vice versa.
        //
        // Actually, the difference is: Reference onlyOwner requires sender == owner, so if sender != owner the
        // call reverts regardless of the callee. Buggy requires sender != owner, so the call proceeds to the
        // callee. If the callee REVERTS, the buggy reverts too. So both revert and ok is false in both.
        // That does NOT distinguish them.
        //
        // To distinguish, we need a callee that DOES NOT revert in its fallback (succeeds).
        // Reference reverts (sender != owner, modifier fails) -> ok = false.
        // Buggy proceeds (sender != owner, modifier passes), callee succeeds -> ok = true.
        // So we test with a callee that is an EOA (always succeeds). For an EOA, both reference and buggy?
        // Reference: sender != owner -> onlyOwner fails, call reverts -> ok = false.
        // Buggy: sender != owner -> onlyOwner passes, sends value and data to EOA, succeeds -> ok = true.
        //
        // Therefore, for sender != owner and callee = ANY EOA, reference reverts, buggy succeeds.
        // EOA target is simply an arbitrary non-contract address; we can use a pre-calculated address or
        // deploy nothing. A call to an EOA always returns true with no code execution. That is allowed.
        // So the adversary is just a raw address, no helper needed. We can directly use `address(uint160(someVal))`?
        // But the fuzzer gives us `address sender`; it can be any EOA. For callee, we can use `makeAddr("some")`,
        // but that's also an EOA. The simplest: pass a fuzzed `address target` and assume it's EOA by 
        // ensuring its code size is 0. That's valid.
        //
        // Yet the prompt says: "if the difference only manifests through the BEHAVIOUR OF AN EXTERNAL PARTY —
        // a low-level call/transfer/send to a callee that FAILS or REVERTS ... you MUST DEPLOY a minimal helper".
        // Here, the difference manifests with a callee that SUCCEEDS (an EOA succeeds, a contract with unrevert fallback succeeds).
        // Does that require a helper? The rule mentions failing/reverting callee or re-entrant caller. EOA is not a failing callee.
        // But the earlier "REQUIRED" clause might be misinterpreted. To be safe, we'll add a trivial "Succeder" helper
        // that does nothing and returns true. This guarantees the low-level call succeeds. That's better than relying on EOA.
        // The fuzzer supplies the data and value; the helper is just an always-success contract.
        // This conforms to the adversarial counterparty rule: a helper that embodies the behavior (always success),
        // ensuring the buggy version can succeed while reference fails.
        // We'll deploy `SuccessCal` contract.
        // The assertion: if sender != owner, the call SHOULD revert (ok == false) in the reference.
        // In buggy, it succeeds (ok == true). For sender == owner, both succeed because modifier passes in reference too?
        // Actually, reference owner passes, buggy fails (require(sender!=owner) fails). But we want a single assertion that
        // holds for ALL admissible inputs in reference, and fails for some in buggy. If we include sender == owner,
        // reference would have ok==true, but buggy would have ok==false. That's also a difference, but then the rule
        // must capture both cases. Simple property: "ok equals (sender == owner)" for reference?
        // Reference: onlyOwner -> if sender==owner -> sendMoney proceeds -> callee succeeds -> ok=true;
        //            if sender!=owner -> revert -> ok=false.
        // So reference satisfies: ok == (sender == owner).
        // Buggy: onlyOwner inverted -> if sender!=owner -> proceeds -> ok=true;
        //        if sender==owner -> revert -> ok=false.
        // So buggy satisfies: ok == (sender != owner).
        // Thus the universal property that holds for reference: `ok == (sender == owner)`.
        // The buggy version violates this property whenever sender != owner (for sender != owner, reference says false, buggy says true).
        // So we can assert that.
        // We deploy a SuccessCal helper to make callee always succeed.
        //
        // Note: we must not constrain sender too much, but we need to distinguish. We'll fuzz sender, value, data.
        // vm.assume(sender != address(this)) because test contract is often the owner? No, owner is c.owner() which is msg.sender
        // of `new C()`, which is the test contract itself (In setUp, msg.sender is the deployer = this test contract). So owner = address(this).
        // So sender will be fuzzed, can be owner (address(this)) or not.
        // To keep domain wide, we don't exclude owner. The property holds for all sender.
        // For sender == owner, both reference and buggy agree? No, reference true, buggy false. That's also a violation.
        // So the fuzzer will find a violating sender.
        // We must prevent stack overflow or other issues, simple vm.assume(sender != address(0)).
        // Deal sender the value to send.
        //
        vm.assume(sender != address(0));
        SuccessCal cal = new SuccessCal();
        vm.deal(sender, value);

        vm.prank(sender);
        bool ok;
        try c.sendMoney(address(cal), value, data) { ok = true; } catch { ok = false; }

        // Reference property: ok == (sender == c.owner())
        assertTrue(ok == (sender == c.owner()));
    }
}

