pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _value, bytes calldata _data) public {
        // Deploy an adversarial counterparty that always fails on a call
        Reverter reverter = new Reverter();
        // Ensure C has enough balance to send and fund it
        vm.deal(address(c), _value);
        // Start a prank as the owner to pass the onlyOwner modifier
        vm.startPrank(c.owner());
        // The call is expected to fail; we catch whether it reverts
        bool reverted;
        try c.sendMoney(address(reverter), _value, _data) {
            reverted = false;
        } catch {
            reverted = true;
        }
        vm.stopPrank();
        // The property: calling sendMoney on a failing target must always revert.
        // The correct contract reverts (reverted == true); the buggy one does not (reverted == false).
        assertTrue(reverted);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}
